export type Order = { "active_payment_attempt"?: { /** RFC3339 timestamp. Format: date-time. */ "completed_at"?: string; "expected_outstanding_money": MoneyValue; /** Reason code for an attempt failure or interrupted payment step, when available. For payment declines, inspect each payment leg's last_payment_error.code. Unmapped values are returned as attempt_failed. */ "failure_code"?: "card_declined" | "insufficient_funds" | "bank_account_closed" | "bank_account_not_found" | "bank_debit_not_authorized" | "bank_account_restricted" | "bank_debit_limit_exceeded" | "authentication_required" | "payment_blocked" | "expired_card" | "incorrect_cvc" | "processing_error" | "payment_method_unavailable" | "payment_method_declined" | "payment_not_completed" | "payment_action_expired" | "payment_method_temporarily_unavailable" | "payment_failed" | "authorization_canceled" | "coupon_reservation_failed" | "invalid_payment_source" | "inventory_unavailable" | "order_changed_before_payment" | "order_payment_customer_mismatch" | "payment_attempt_canceled" | "payment_attempt_expired" | "payment_authorization_canceled" | "payment_authorization_expired" | "payment_confirmation_rejected" | "payment_confirm_outcome_unknown" | "payment_link_capacity_claim_failed" | "payment_link_capacity_validation_failed" | "payment_method_activation_pending" | "payment_method_required" | "payment_option_not_allowed" | "payment_option_unavailable" | "payment_source_binding_failed" | "payment_source_conflict" | "payment_source_not_updatable" | "payment_source_ownership_mismatch" | "receipt_email_failed" | "resource_guarantee_failed" | "setup_action_unavailable" | "setup_canceled" | "setup_cancellation_outcome_unknown" | "setup_cancellation_pending" | "setup_confirmation_outcome_unknown" | "setup_hold_acquisition_failed" | "setup_preparation_outcome_unknown" | "setup_processing" | "setup_result_incomplete" | "setup_status_unknown" | "tip_allocation_sync_failed" | "zero_balance_hold_acquisition_failed" | "attempt_failed" | (string & {}); /** Explanation of an attempt failure or interrupted payment step, when available. For payment declines, inspect each payment leg's last_payment_error.message. */ "failure_message"?: string; "gift_card_redemptions"?: Array<PaymentAttemptGiftCardRedemption>; /** Whether the attempt can continue through PayOrder with action: resume and this payment_attempt_id after any pending client action is complete. If false, check status before starting another payment; the attempt may still be in progress. */ "is_resumable": boolean; "mode": "payment" | "setup" | "settlement" | (string & {}); "payment_attempt_id": string; "payment_intents"?: Array<PaymentAttemptPaymentIntent>; "pending_actions"?: Array<PendingPaymentAction>; /** RFC3339 timestamp. Format: date-time. */ "started_at"?: string; "status": "processing" | "requires_action" | "requires_capture" | "partially_succeeded" | "requires_retry" | "finalizing" | "succeeded" | "failed" | "expired" | "canceled" | (string & {}); }; "applied_discounts"?: Array<AppliedDiscount>; "authorization_amounts"?: { "authorized_money": MoneyValue; "capturable_money": MoneyValue; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; }; /** What the buyer can do with the order, in this order: start_return, then resend_receipt. A buyer's read through a customer session on /v1/me, or in Flint's buyer account, lists both every time; a merchant read gets an empty list. A list of orders leaves start_return out, since only a read of one order checks return eligibility. start_return is due when the last open return window ends. Example: []. */ "buyer_actions": Array<BuyerAction>; "buyer_email"?: string; "buyer_note"?: string; /** Phone the buyer gave when payment started, in E.164 format: the pay request's buyer_phone, or the phone saved on the paying checkout session. It does not change the linked customer. */ "buyer_phone"?: string; "charges"?: Array<OrderCharge>; "checkout_session_ids"?: Array<string>; /** Internal reason supplied when the order was closed. This is not shown to the buyer. */ "closed_reason"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "customer_id"?: string; /** The shipment or local-delivery destination committed for this order. Payment freezes this value; fulfillment recipient changes do not replace it. */ "delivery_destination"?: { "address": OrderDeliveryDestinationAddress; /** Delivery selection that controls this destination, when checkout collected it. */ "delivery_selection_id"?: string; /** Time payment froze this destination. Format: date-time. */ "frozen_at"?: string; "recipient"?: OrderDeliveryDestinationRecipient; "source": "delivery_selection" | "api" | "dashboard" | (string & {}); }; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "fulfillments"?: Array<Fulfillment>; "gift_card_estimate"?: { "can_pay": boolean; "gift_card_money": GiftCardMoney; "gift_cards": Array<OrderGiftCardAllocation>; "is_reserved": boolean; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "order_revision": string; "processor_money": GiftCardMoney; }; "gift_card_settlements"?: Array<OrderGiftCardSettlement>; "gift_card_tender_enabled"?: boolean; "gift_cards"?: Array<OrderGiftCardSelection>; "internal_note"?: string; "inventory_exception_status"?: "paid_inventory_failed" | "resolved" | (string & {}); /** The reservation holding stock for this order, when one exists. */ "inventory_reservation_id"?: string; /** Where this order's tracked demand is routed. Required before an order containing tracked variants can hold stock. */ "inventory_routing_source"?: { "inventory_allocation_policy_id"?: string; "inventory_allocation_policy_version_id"?: string; "location_id"?: string; "location_ids"?: Array<string>; "type": "fixed_location" | "policy" | "policy_version" | (string & {}); }; "line_items": Array<OrderLineItem>; "merchant_id"?: string; "metadata"?: Record<string, string>; "order_id": string; "order_number"?: string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "order_revision"?: string; "origin"?: "virtual_terminal" | "payment_link" | "checkout" | "api" | "subscription" | (string & {}); "payment_collection"?: { "stripe"?: PaymentCollectionStripe; }; "payment_intent_ids"?: Array<string>; "payment_intents"?: Array<ExpandedPaymentIntentSummary>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "plan_id"?: string; "pricing_amounts": { "charge_money": MoneyValue; "discount_money": MoneyValue; "requested_tip_money": MoneyValue; "subtotal_money": MoneyValue; "tax_money": MoneyValue; "total_money": MoneyValue; }; "purchased_event"?: { "location"?: string; "name": string; /** RFC3339 timestamp. Format: date-time. */ "starts_at"?: string; "timezone"?: string; }; "refund_ids"?: Array<string>; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "requested_tip"?: RequestedTip; /** Value applied to this order from items the buyer returned, such as an exchange's replacement order. Included in settlement_amounts.paid_money. */ "return_credit_settlements"?: Array<OrderReturnCreditSettlement>; "settlement_amounts": { "balance_money": SignedMoney; "credit_money": MoneyValue; "net_collected_money": MoneyValue; "outstanding_money": MoneyValue; "paid_money": MoneyValue; "refunded_money": MoneyValue; "settled_tip_money": MoneyValue; }; "setup_collection"?: { "stripe"?: PaymentCollectionStripe; }; "status": "open" | "closed" | (string & {}); "subscription"?: (({ /** Format: int32. */ "billing_anchor_day": number; "cancel_at_period_end": boolean; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "current_period_end"?: string; "current_period_start"?: string; "customer_id": string; /** RFC3339 timestamp. Format: date-time. */ "next_billing_at"?: string; "plan_id": string; "status": "trialing" | "active" | "paused" | "past_due" | "canceled" | "incomplete" | (string & {}); "subscription_id": string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "subscription_id"?: string; "subscription_plan"?: (({ "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Format: int32. */ "billing_interval_count": number; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; "description"?: string; "line_items"?: Array<SubscriptionPlanLineItem>; "name": string; "plan_id": string; "setup_fee_money"?: MoneyValue; "status": "active" | "archived" | (string & {}); /** Format: int32. */ "trial_period_days"?: number; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "tax": { /** Identifies which automatic tax behavior applies to this order. connected means the account's tax connection calculated it. standard marks an order calculated before automatic tax required a tax connection. */ "automatic_profile"?: "standard" | "connected" | (string & {}); "available_location_inputs"?: Array<string>; "enabled": boolean; "exemption"?: OrderTaxExemption; /** Normalized reason the most recent tax calculation could not complete. */ "failure_reason"?: "calculation_unavailable" | "location_unsupported" | "rate_unavailable" | (string & {}); "location"?: OrderTaxLocation; "mode": "automatic" | "external" | (string & {}); "status": "not_required" | "requires_location" | "calculated" | "exempt" | "incomplete" | (string & {}); "tax_breakdowns"?: Array<TaxBreakdown>; /** Explains why tax was charged or zero for this order. */ "taxability_reason": "standard_rated" | "not_taxable" | "customer_exempt" | "tax_disabled" | "no_jurisdiction" | "location_required" | (string & {}); }; "tips"?: Array<Tip>; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; };
